class SearchPopularParams(BaseModel):
    query: Annotated[str, Field(examples=["basketball"], max_length=100, min_length=1)]
    """
    The topic to look up, such as basketball.
    """
    cursor: Annotated[
        str | None, Field(max_length=512, pattern="^[A-Za-z0-9+/=_\\-:.]{1,512}$")
    ] = None
    """
    The `cursor` from the previous page. Omit it for the first page.
    """


